4	/** The rules a claim must keep to be added to a person (see AddClaim), checked without writing anything. */
5	public final class ClaimRules {
6	
7	    private ClaimRules() {
8	    }
9	
10	    /** The claim's date (the sheet's entry date, else its today, when none was given) and the due-by it would be fixed with (see dueBy);
11	     *  a due-by inside a closed period or a date after the person's retirement date is refused, as is a negative amount that does not
12	     *  correct a SETTLED claim (see Corrections), or a reference already used on the sheet (see checkRef). */
13	    public static Checked check(Person person, ClaimValues values, SettingRepository settings, PeriodRepository periods,
14	            ClaimRepository claims, HolidayRepository holidays) throws InvalidClaimException {
15	        LocalDate date = values.date() != null ? values.date() : settings.claimDate(person.sheetId());
16	        int terms = terms(person, date, settings);
17	        LocalDate dueBy = holidays.businessDaysAfter(person.sheetId(), date, terms);
18	        if (periods.closedOn(person.sheetId(), dueBy)) {
19	            throw new InvalidClaimException("The claim's due-by is inside a closed period");
20	        }
21	        if (!person.mayClaimOn(date)) {
22	            throw new InvalidClaimException("The claim's date is after the person's retirement date");
23	        }
24	        checkRef(person.sheetId(), values, null, claims);
25	        return new Checked(date, Corrections.check(person.sheetId(), person.id(), values, claims), dueBy, terms);
26	    }
27	
28	    /** Refuses a reference another claim of the sheet already has, comparing without regard to case; {@code self} is the
29	     *  claim being edited (null for an add), whose own reference does not count. */
30	    public static void checkRef(String sheetId, ClaimValues values, Long self, ClaimRepository claims) throws InvalidClaimException {
31	        if (values.ref() != null && claims.refUsed(sheetId, values.ref(), self)) {
32	            throw new InvalidClaimException("The reference " + values.ref() + " is already used on the sheet");
33	        }
34	    }
35	
36	    /** The due-by a claim of the person dated the date is fixed with as it is added: the terms-th business day after its date (see
37	     *  HolidayRepository.businessDaysAfter), the terms being the person's own, else those of their grade in force on that date (the
38	     *  holidays on the sheet now decide; one added later works it out again, see ClaimRepository#refixDueBys). */
39	    public static LocalDate dueBy(Person person, LocalDate date, SettingRepository settings, HolidayRepository holidays) {
40	        return holidays.businessDaysAfter(person.sheetId(), date, terms(person, date, settings));
41	    }
42	
43	    /** The terms a claim of the person dated the date is fixed with: the person's own, else those of their grade in force on
44	     *  that date. The claim keeps them, so its due-by can be worked out again when a holiday is added (see ClaimRepository#refixDueBys). */
45	    public static int terms(Person person, LocalDate date, SettingRepository settings) {
46	        return settings.terms(person.sheetId(), person.terms(), person.gradeOn(date), date);
47	    }
48	
49	    /** A claim's date, the number it corrects (null when none), its due-by and the terms it was fixed with, once its rules are kept. */
50	    public record Checked(LocalDate date, String corrects, LocalDate dueBy, int terms) {
51	    }
52	}
