56	/** The figures a claim has: live, fixed when settled, or bound by a statement. */
57	public final class ClaimDue {
58	
59	    private ClaimDue() {
60	    }
61	
62	    /** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do. */
63	    public static boolean counts(Claim claim) {
64	        return isOpen(claim) || claim.status() == ClaimStatus.SETTLED;
65	    }
66	
67	    /** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim but for its statement binding). */
68	    public static boolean isOpen(Claim claim) {
69	        return claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING;
70	    }
71	
72	    /** Whether a claim counts toward the live totals (claimed, due-totals, a period's due-total): one that counts,
73	     *  unless it is open (OPEN or PENDING), not bound by a statement, and dated within a hold of its person (null: none). */
74	    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person) {
75	        return counts(claim) && !(isOpen(claim) && !bound(claim) && person != null && person.heldOn(claim.date()));
76	    }
77	
78	    /** Whether a claim is deferred on the given today: an OPEN claim deferred until a date after it. Until then it
79	     *  counts in no total, is not overdue, cannot be settled and is left unbound by a statement; from that day on
80	     *  it is an OPEN claim like any other. */
81	    public static boolean deferred(Claim claim, java.time.LocalDate today) {
82	        return claim.status() == ClaimStatus.OPEN && claim.deferredUntil() != null
83	                && claim.deferredUntil().isAfter(today);
84	    }
85	
86	    /** Whether a claim counts toward the live totals on the given today: as {@link #countsLive(Claim,
87	     *  net.officefloor.hq.app.person.Person)}, unless it is deferred, or it is open, not bound by a statement, and its
88	     *  person's retirement date is reached on today. */
89	    public static boolean countsLive(Claim claim, net.officefloor.hq.app.person.Person person,
90	            java.time.LocalDate today) {
91	        return countsLive(claim, person) && !deferred(claim, today) && !retiredOut(claim, person, today);
92	    }
93	
94	    /** Whether a claim leaves the live totals for its person's retirement: it is open (OPEN or PENDING), not bound by
95	     *  a statement, and its person's retirement date is on or before today (null person: never). */
96	    public static boolean retiredOut(Claim claim, net.officefloor.hq.app.person.Person person,
97	            java.time.LocalDate today) {
98	        return isOpen(claim) && !bound(claim) && person != null && person.retiredOn(today);
99	    }
100	
101	    /** The claim's rate figure: its amount at the grade's rate in force on its date, rounded to two decimals by the
102	     *  claim's rounding (see Rounding); null when no rate applies. The floor is applied last, after the late charge
103	     *  (see LateCharge#add). */
104	    public static BigDecimal live(Claim claim, String grade, RateRepository rates, Rounding rounding) {
105	        Rate rate = rates.find(claim.sheetId(), grade, claim.date());
106	        if (rate == null) {
107	            return null;
108	        }
109	        return claim.amount().multiply(rate.rate()).movePointLeft(2).setScale(2, rounding.mode(claim));
110	    }
111	
112	    /** Whether the claim is a correction: its amount is negative. */
113	    public static boolean isCorrection(Claim claim) {
114	        return claim.amount().signum() < 0;
115	    }
116	
117	    /** The figure the claim shows: fixed when settled, else the one a statement bound it to (never while PENDING),
118	     *  else its live rate figure; null when it has none (n/a). */
119	    public static BigDecimal figure(Claim claim, String grade, RateRepository rates, Rounding rounding) {
120	        if (claim.due() != null) {
121	            return claim.due();
122	        }
123	        return bound(claim) ? claim.statedDue() : live(claim, grade, rates, rounding);
124	    }
125	
126	    /** Whether the claim keeps a figure whatever the rates are: fixed when settled, or bound by a statement. */
127	    public static boolean kept(Claim claim) {
128	        return claim.due() != null || (bound(claim) && claim.statedDue() != null);
129	    }
130	
131	    /** Whether a statement binds the claim now: it is stated and not PENDING. */
132	    public static boolean bound(Claim claim) {
133	        return claim.stated() && claim.status() != ClaimStatus.PENDING;
134	    }
135	
136	    /** The status a claim had at the end of a day, as its status log (oldest first) records it: that of the last line
137	     *  made on or before the day; null when the claim was added after it. */
138	    public static ClaimStatus statusAsOf(java.util.List<ClaimLogLine> log, java.time.LocalDate day) {
139	        ClaimStatus status = null;
140	        for (ClaimLogLine line : log) {
141	            if (!line.date().isAfter(day)) {
142	                status = line.status();
143	            }
144	        }
145	        return status;
146	    }
147	
148	    /** The claim as it would be with another status, all else kept. */
149	    public static Claim withStatus(Claim c, ClaimStatus status) {
150	        return new Claim(c.id(), c.sheetId(), c.personId(), c.amount(), c.date(), c.note(), status, c.number(), c.due(),
151	                c.openedBy(), c.stated(), c.statedDue(), c.corrects(), c.dueBy(), c.deferredUntil(), c.proofs(), c.splitFrom(), c.ref(), c.tags());
152	    }
153	}
154	=== Rounding
155	
156	
157	/**
158	 * How a claim's live figures (the rate step and the late charge) are rounded to two decimals: a claim dated before
159	 * the sheet's policy date (its today while the policy date is blank) rounds half up, one dated on or after it half to
160	 * even. A correction rounds by the date of the claim it corrects, not its own.
161	 */
162	public record Rounding(LocalDate policy, ClaimRepository claims) {
163	
164	    public static Rounding of(String sheetId, SheetRepository sheets, SettingRepository settings, ClaimRepository claims) {
165	        LocalDate policy = settings.policyDate(sheetId);
166	        return new Rounding(policy == null ? sheets.today(sheetId) : policy, claims);
167	    }
168	
169	    /** The date that decides how the claim rounds: the corrected claim's date for a correction, else its own. */
170	    public static LocalDate roundsOn(Claim claim, ClaimRepository claims) {
171	        if (claim.corrects() != null) {
172	            Claim corrected = claims.findByNumber(claim.sheetId(), claim.personId(), claim.corrects());
173	            if (corrected != null) {
174	                return corrected.date();
175	            }
176	        }
177	        return claim.date();
178	    }
179	
180	    /** The rounding the claim's live figures take. */
181	    public RoundingMode mode(Claim claim) {
182	        return roundsOn(claim, claims).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
183	    }
184	}
185	=== LateCharge
186	
187	
188	/**
189	 * The late charge on a sheet as of its today: an overdue claim (OPEN or PENDING, its due-by — fixed when it was added — plus
190	 * its grace before today; see lateFrom) gains, for every full 30 days it is overdue, the late percent in force on that boundary
191	 * date (its due-by plus its grace plus 30, 60, 90 ... days) of its figure plus the charges of the boundaries before it (compounding), each rounded to two decimals by the claim's rounding (see Rounding), added up; a
192	 * boundary whose percent is 0.00 adds nothing. The charge is never bound by a statement (it follows today); settling freezes it into the claim's due.
193	 * The floor is applied last: a claim's live due is the greater of the floor in force on its date and its figure plus its charge.
194	 */
195	public record LateCharge(LocalDate today, Function<LocalDate, BigDecimal> pct, Rounding rounding,
196	        Function<Claim, Integer> grace) {
197	
198	    /** The days in each step of the charge. */
199	    public static final int DAYS = 30;
200	
201	    public static LateCharge of(String sheetId, SheetRepository sheets, SettingRepository settings,
202	            ClaimRepository claims) {
203	        return new LateCharge(sheets.today(sheetId), (date) -> settings.latePct(sheetId, date),
204	                Rounding.of(sheetId, sheets, settings, claims),
205	                (claim) -> settings.graceOf(sheetId, claim.personId(), claim.date()));
206	    }
207	
208	    /** The date a claim is late from: its due-by plus the grace of its person's grade in force on its date (none: its
209	     *  due-by). The claim is overdue once this is before today; its 30-day boundaries count from it. */
210	    public LocalDate lateFrom(Claim claim) {
211	        return claim.dueBy().plusDays(grace.apply(claim));
212	    }
213	
214	    /** The charge on the claim with the given figure: zero when it is not overdue a full 30 days, has no figure, is
215	     *  a correction, or is deferred. */
216	    public BigDecimal on(Claim claim, BigDecimal figure) {
217	        if (figure == null || !ClaimDue.isOpen(claim) || claim.due() != null || ClaimDue.isCorrection(claim)
218	                || ClaimDue.deferred(claim, today)) {
219	            return BigDecimal.ZERO.setScale(2);
220	        }
221	        LocalDate from = lateFrom(claim);
222	        long overdue = ChronoUnit.DAYS.between(from, today);
223	        long steps = overdue <= 0 ? 0 : overdue / DAYS;
224	        BigDecimal charge = BigDecimal.ZERO.setScale(2);
225	        for (long step = 1; step <= steps; step++) {
226	            BigDecimal boundary = pct.apply(from.plusDays(step * DAYS));
227	            charge = charge.add(figure.add(charge).multiply(boundary).movePointLeft(2).setScale(2, rounding.mode(claim)));
228	        }
229	        return charge;
230	    }
231	
232	    /** The claim's due: the figure with its charge added on top, at least the floor (none for a correction, nor for a
233	     *  settled figure, which stays frozen); null when it has none. */
234	    public BigDecimal add(Claim claim, BigDecimal figure, BigDecimal floor) {
235	        if (figure == null) {
236	            return null;
237	        }
238	        BigDecimal due = figure.add(on(claim, figure));
239	        return claim.due() != null || ClaimDue.isCorrection(claim) ? due : due.max(floor);
240	    }
241	}
