245	/**
246	 * The number a claim receives as it is opened. While the sheet's period-numbering-from setting is a date and the
247	 * sheet's today is on or after it, the claim is numbered within the period containing its due-by, {@code <period>-<n>}
248	 * counting from 1 in each period, or {@code X-<n>} in its own sequence when no period contains it. Otherwise it takes
249	 * the sheet-wide next number (1, 2, ...), which continues where it left off.
250	 */
251	public final class ClaimNumbering {
252	
253	    private ClaimNumbering() {
254	    }
255	
256	    public static String next(Claim claim, ClaimRepository claims, PeriodRepository periods, SettingRepository settings,
257	            SheetRepository sheets) {
258	        String sheet = claim.sheetId();
259	        if (!perPeriod(sheet, settings, sheets)) {
260	            return String.valueOf(claims.nextNumber(sheet));
261	        }
262	        Period period = periods.containing(sheet, claim.dueBy());
263	        String key = period == null ? "X" : period.name();
264	        return key + "-" + claims.nextPeriodNumber(sheet, key);
265	    }
266	
267	    /** Whether claims are numbered per period now: the period-numbering-from setting is a date on or before today. */
268	    public static boolean perPeriod(String sheet, SettingRepository settings, SheetRepository sheets) {
269	        LocalDate from = settings.periodNumberingFrom(sheet);
270	        return from != null && !sheets.today(sheet).isBefore(from);
271	    }
272	}
273	=== ClaimResponse
274	
275	
276	/** A claim as sent to the screen: the amount as text with two decimals, so it is never rounded through a float;
277	 *  the number is null when the claim has none; due is the due fixed when settled (two decimals), null while it is
278	 *  live; openedBy is who opened it, null when never opened; stated is whether it is bound to the figure statedDue
279	 *  (two decimals, null when it had none) by its person's last statement; corrects is the number of the claim a
280	 *  correction corrects (null for any other claim); roundsOn is the date that decides how its live figures round
281	 *  (the corrected claim's date for a correction, else its own; see Rounding); dueBy (yyyy-MM-dd) is its due-by, fixed
282	 *  when it was added; deferred is whether it is deferred on the sheet's today (see ClaimDue#deferred) and deferredUntil
283	 *  (yyyy-MM-dd) the date it was last deferred until (shown even once that date has passed), null when never deferred; proofs is its proofs count; splitFrom is the number of the claim it was split from (null for any other claim); log is its status log, oldest first: each status it has had, who made the change, the sheet's
284	 *  today (yyyy-MM-dd) then, and its due as shown at that moment (two decimals, or n/a); lockedBy is who has its editor
285	 *  open (null when no one does); lateEntry is whether it was added while its period was soft-closed; reminded (yyyy-MM-dd) is the last day a
286	 *  reminder was written for it, null when none; ref is its external reference, null when none; tags are its tags, sorted (empty when none); comments are its comments in the order written, each with who wrote it and
287	 *  the sheet's today (yyyy-MM-dd) then; batch is the number of the bulk settle batch that settled it, null when none did. */
288	public record ClaimResponse(long id, String sheetId, long personId, String amount, String date, String note,
289	        String status, String number, String due, String openedBy, boolean stated, String statedDue, String corrects,
290	        String roundsOn, String dueBy, boolean deferred, String deferredUntil, int proofs, String splitFrom, List<LogLine> log,
291	        String lockedBy, boolean lateEntry, String reminded, String ref, List<String> tags,
292	        List<Comment> comments, Integer batch) {
293	
294	    /** One comment on a claim as sent to the screen. */
295	    public record Comment(String by, String date, String text) {
296	    }
297	
298	    /** One line of a claim's status log as sent to the screen. */
299	    public record LogLine(String status, String by, String date, String due) {
300	    }
301	
302	    public static ClaimResponse from(Claim claim, ClaimRepository claims, ClaimLogRepository log, LocalDate today) {
303	        return from(claim, claims, log.of(claim.sheetId(), claim.id()), today);
304	    }
305	
306	    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today) {
307	        return from(claim, claims, log, today, claims.lockedBy(claim.sheetId(), claim.id()),
308	                claims.lateEntry(claim.sheetId(), claim.id()), claims.remindedOn(claim.sheetId(), claim.id()),
309	                claims.comments(claim.sheetId(), claim.id()), claims.batchOf(claim.sheetId(), claim.id()));
310	    }
311	
312	    public static ClaimResponse from(Claim claim, ClaimRepository claims, List<ClaimLogLine> log, LocalDate today, String lockedBy,
313	            boolean lateEntry, LocalDate reminded, List<ClaimComment> comments, Integer batch) {
314	        boolean deferred = ClaimDue.deferred(claim, today);
315	        return new ClaimResponse(claim.id(), claim.sheetId(), claim.personId(), claim.amount().toPlainString(),
316	                claim.date().toString(), claim.note(), claim.status().name(), claim.number(),
317	                claim.due() == null ? null : claim.due().toPlainString(), claim.openedBy(), claim.stated(),
318	                claim.statedDue() == null ? null : claim.statedDue().toPlainString(), claim.corrects(),
319	                Rounding.roundsOn(claim, claims).toString(), claim.dueBy().toString(),
320	                deferred, claim.deferredUntil() == null ? null : claim.deferredUntil().toString(), claim.proofs(), claim.splitFrom(),
321	                log.stream().map((l) -> new LogLine(l.status().name(), l.by(), l.date().toString(), l.due())).toList(),
322	                lockedBy, lateEntry, reminded == null ? null : reminded.toString(), claim.ref(),
323	                claim.tags() == null ? List.of() : List.of(claim.tags().split(",")),
324	                comments.stream().map((m) -> new Comment(m.by(), m.date().toString(), m.text())).toList(), batch);
325	    }
