330	/** A claim's values once validated. {@code date} is null when none was given (the sheet's today applies). {@code corrects} is the number of
331	 *  the claim a correction corrects (null when none was given). {@code by} is who gives them. {@code ref} is its external reference,
332	 *  surrounding spaces removed (null when none, or a blank one, was given). {@code tags} are its tags as stored (see #tags; null when none). */
333	public record ClaimValues(BigDecimal amount, LocalDate date, String note, String corrects, String by, String ref, String tags) {
334	    private static final Pattern AMOUNT = Pattern.compile("-?\\d{1,15}(\\.\\d{1,2})?");
335	
336	    /** The request's values by the claim form's rules (see ValidateClaim). */
337	    public static ClaimValues from(ClaimRequest request) throws InvalidClaimException {
338	        String amount = request == null || request.amount() == null ? "" : request.amount().trim();
339	        if (!AMOUNT.matcher(amount).matches()) {
340	            throw new InvalidClaimException("The amount must be a number with up to two decimals");
341	        }
342	        String date = request.date() == null ? "" : request.date().trim();
343	        LocalDate parsed = null;
344	        if (!date.isEmpty()) {
345	            try {
346	                parsed = LocalDate.parse(date);
347	            } catch (DateTimeParseException e) {
348	                throw new InvalidClaimException("The date must be yyyy-MM-dd");
349	            }
350	        }
351	        String note = request.note() == null ? "" : request.note().trim();
352	        String corrects = request.corrects() == null ? "" : request.corrects().trim();
353	        String ref = request.ref() == null ? "" : request.ref().trim();
354	        return new ClaimValues(new BigDecimal(amount).setScale(2), parsed, note, corrects.isEmpty() ? null : corrects,
355	                request.by() == null ? "" : request.by().trim(), ref.isEmpty() ? null : ref,
356	                tags(request.tags()));
357	    }
358	
359	    /** Comma separated tags as stored: each trimmed and in lower case, blanks and repeats dropped, sorted, joined by
360	     *  commas; null when none is left. */
361	    public static String tags(String typed) throws InvalidClaimException {
362	        if (typed == null) {
363	            return null;
364	        }
365	        String joined = String.join(",", new TreeSet<>(Arrays.stream(typed.split(",")).map((t) -> t.trim().toLowerCase(Locale.ROOT))
366	                .filter((t) -> !t.isEmpty()).toList()));
367	        if (joined.length() > 2000) {
368	            throw new InvalidClaimException("The tags are too long");
369	        }
370	        return joined.isEmpty() ? null : joined;
371	    }
372	
373	    /** The reference as compared: without regard to case. */
374	    public static String refKey(String ref) {
375	        return ref == null ? null : ref.toLowerCase(Locale.ROOT);
376	    }
377	}
378	=== ApplyClaim
