380	
381	/** Applies the edited values; only a DRAFT claim can be edited (an open claim is voided and a new one added instead),
382	 * and a claim whose due-by (which an edit leaves as it is) falls inside a closed period, or left or moved after its person's retirement date,
383	 * is refused, as is a reference another claim of the sheet already has (see ClaimRules.checkRef). */
384	public class ApplyClaim {
385	    public void apply(@Val Claim claim, @Val ClaimValues values, SheetRepository sheets, PeriodRepository periods,
386	            PersonRepository people, ClaimRepository claims, Out<Claim> changed) throws InvalidClaimException {
387	        if (claim.status() != ClaimStatus.DRAFT) {
388	            throw new InvalidClaimException("Only a DRAFT claim can be edited");
389	        }
390	        LocalDate date = values.date() != null ? values.date() : sheets.today(claim.sheetId());
391	        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
392	            throw new InvalidClaimException("The claim's due-by is inside a closed period");
393	        }
394	        Person person = people.find(claim.sheetId(), claim.personId());
395	        if (person != null && !person.mayClaimOn(date)) {
396	            throw new InvalidClaimException("The claim's date is after the person's retirement date");
397	        }
398	        ClaimRules.checkRef(claim.sheetId(), values, claim.id(), claims);
399	        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), values.amount(), date, values.note(), claim.status(),
400	                claim.number(), claim.due(), claim.openedBy(), claim.stated(), claim.statedDue(),
401	                Corrections.check(claim.sheetId(), claim.personId(), values, claims), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), values.ref(), values.tags()));
402	    }
403	}
404	=== ApplyClaimStatus
405	
406	
407	/**
408	 * Moves the claim to its new status: DRAFT to OPEN, OPEN to SETTLED (or PENDING), PENDING to SETTLED (approve) or back
409	 * to OPEN (reject), DRAFT, OPEN or PENDING to VOID. A voided claim keeps
410	 * its number (never given again). Settling fixes the claim's due: its amount at its
411	 * person's grade's rate in force on the claim's date, rounded by its rounding (see Rounding) and at least the sheet's floor (left live when no rate applies),
412	 * or the figure a statement bound it to, with its late charge as of the sheet's today frozen in (see LateCharge).
413	 * Opening records who opened the claim; that user cannot settle nor approve it (four eyes), nor can the user who last
414	 * edited it (see ClaimRepository#editedBy). A claim whose due is
415	 * above the proof threshold in force on its date (its person's grade's on that date when one is set, else the sheet's; if any) cannot be settled nor approved while its proofs
416	 * count is 0 (checked before the clerk limit, so it never goes PENDING); a due of n/a is within any threshold. A claim whose due-by falls inside a closed
417	 * period cannot change status, nor can a deferred claim be settled (see ClaimDue#deferred). A clerk (any user not made a steward) settling a claim whose due is above the sheet's
418	 * clerk limit, if it has one, makes it PENDING instead (its due left live, not bound by a statement); a due of n/a is
419	 * within any limit. A steward settles anything. Only a steward approves a PENDING claim (fixing its live figure, late
420	 * charge included, at that moment) or rejects it (OPEN again, bound again by its statement if one bound it).
421	 * A claim whose due (as it shows: its live figure at least the floor, or the figure a statement bound it to) is above
422	 * the sheet's note threshold in force on its date (if it has one) cannot be opened while its note is empty; a due of
423	 * n/a is within any threshold (see #needsNote).
424	 * Opening, settling and voiding are each taken only by the roles the sheet's permission allows (see SettingRepository#permits).
425	 * While the sheet has void reasons, a void needs one of them (see VoidReasonRepository); a reason not on its list is refused.
426	 * Only a steward voids a SETTLED claim, and only within 7 days of its settlement (the sheet's today on its status log's
427	 * latest SETTLED line) by the sheet's today; its frozen figure is kept on it but, VOID, it leaves every total.
428	 * Only a steward re-settles a SETTLED claim (not one whose due-by falls inside a closed period): its due is fixed again at the figure
429	 * it would have today as an OPEN claim bound by no statement (today's rates, grades, floor and late charge).
430	 */
431	public class ApplyClaimStatus {
432	
433	    /** How many days after its settlement a steward may still void a SETTLED claim. */
434	    static final int VOID_SETTLED_DAYS = 7;
435	
436	    public void apply(@Val Claim claim, @Val ClaimStatusChange change, PersonRepository people, RateRepository rates,
437	            PeriodRepository periods, SettingRepository settings, RoleRepository roles, SheetRepository sheets, ClaimRepository claims, ClaimLog log, VoidReasonRepository voidReasons, Out<Claim> changed, Out<ClaimNumber> number, Out<PreviousDue> previous) throws InvalidClaimStatusException {
438	        boolean allowed = switch (change.action()) {
439	            case OPEN -> claim.status() == ClaimStatus.DRAFT;
440	            case SETTLE -> claim.status() == ClaimStatus.OPEN;
441	            case APPROVE, REJECT -> claim.status() == ClaimStatus.PENDING;
442	            case VOID -> claim.status() == ClaimStatus.DRAFT || claim.status() == ClaimStatus.OPEN
443	                    || claim.status() == ClaimStatus.PENDING || claim.status() == ClaimStatus.SETTLED;
444	            case RESETTLE -> claim.status() == ClaimStatus.SETTLED;
445	        };
446	        if (!allowed) {
447	            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot be made " + change.to());
448	        }
449	        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
450	            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
451	        }
452	        if (change.action() == ClaimAction.SETTLE && ClaimDue.deferred(claim, sheets.today(claim.sheetId()))) {
453	            throw new InvalidClaimStatusException("A deferred claim cannot be settled until the date it is deferred until");
454	        }
455	        String role = roles.roleOf(claim.sheetId(), change.by());
456	        boolean steward = RoleRepository.STEWARD.equals(role);
457	        String permission = switch (change.action()) {
458	            case OPEN -> "open";
459	            case SETTLE -> "settle";
460	            case VOID -> "void";
461	            default -> null;
462	        };
463	        if (permission != null && !settings.permits(claim.sheetId(), permission, role)) {
464	            throw new InvalidClaimStatusException("A " + role + " may not " + permission + " a claim");
465	        }
466	        if (change.action() == ClaimAction.VOID && !change.reason().isEmpty()
467	                ? !voidReasons.has(claim.sheetId(), change.reason())
468	                : change.action() == ClaimAction.VOID && voidReasons.any(claim.sheetId())) {
469	            throw new InvalidClaimStatusException("A void needs a reason from the sheet's list of void reasons");
470	        }
471	        if (change.action() == ClaimAction.OPEN && needsNote(claim, people, rates, settings,
472	                LateCharge.of(claim.sheetId(), sheets, settings, claims))) {
473	            throw new InvalidClaimStatusException("A claim whose due is above the note threshold needs a note to be opened");
474	        }
475	        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE)
476	                && change.by().equals(claim.openedBy())) {
477	            throw new InvalidClaimStatusException("The user who opened a claim cannot settle nor approve it");
478	        }
479	        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE)
480	                && change.by().equals(claims.editedBy(claim))) {
481	            throw new InvalidClaimStatusException("The user who last edited a claim cannot settle nor approve it");
482	        }
483	        if ((change.action() == ClaimAction.APPROVE || change.action() == ClaimAction.REJECT) && !steward) {
484	            throw new InvalidClaimStatusException("Only a steward approves or rejects a pending claim");
485	        }
486	        if (change.action() == ClaimAction.VOID && claim.status() == ClaimStatus.SETTLED) {
487	            if (!steward) {
488	                throw new InvalidClaimStatusException("Only a steward voids a settled claim");
489	            }
490	            LocalDate settledOn = log.settledOn(claim);
491	            if (settledOn == null || sheets.today(claim.sheetId()).isAfter(settledOn.plusDays(VOID_SETTLED_DAYS))) {
492	                throw new InvalidClaimStatusException("A settled claim can only be voided within "
493	                        + VOID_SETTLED_DAYS + " days of its settlement");
494	            }
495	        }
496	        if (change.action() == ClaimAction.RESETTLE && !steward) {
497	            throw new InvalidClaimStatusException("Only a steward re-settles a claim");
498	        }
499	        ClaimStatus to = change.to();
500	        LateCharge late = LateCharge.of(claim.sheetId(), sheets, settings, claims);
501	        BigDecimal settledDue;
502	        if (change.action() == ClaimAction.RESETTLE) {
503	            Claim asOpen = new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
504	                    claim.note(), ClaimStatus.OPEN, claim.number(), null, claim.openedBy(), false, null,
505	                    claim.corrects(), claim.dueBy(), null, claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags());
506	            settledDue = late.add(asOpen, due(asOpen, people, rates, late.rounding()), settings.floor(claim.sheetId(), claim.date()));
507	        } else {
508	            settledDue = to == ClaimStatus.SETTLED ? late.add(claim, due(claim, people, rates, late.rounding()), settings.floor(claim.sheetId(), claim.date())) : claim.due();
509	        }
510	        if ((change.action() == ClaimAction.SETTLE || change.action() == ClaimAction.APPROVE) && settledDue != null
511	                && claim.proofs() == 0) {
512	            Person person = people.find(claim.sheetId(), claim.personId());
513	            BigDecimal threshold = settings.proofThreshold(claim.sheetId(),
514	                    person == null ? null : person.gradeOn(claim.date()), claim.date());
515	            if (threshold != null && settledDue.compareTo(threshold) > 0) {
516	                throw new InvalidClaimStatusException("A claim whose due is above the proof threshold needs a proof");
517	            }
518	        }
519	        if (change.action() == ClaimAction.SETTLE && settledDue != null && !steward) {
520	            BigDecimal limit = settings.clerkLimit(claim.sheetId());
521	            if (limit != null && settledDue.compareTo(limit) > 0) {
522	                to = ClaimStatus.PENDING;
523	                settledDue = null;
524	            }
525	        }
526	        number.set(new ClaimNumber(claim.number()));
527	        previous.set(new PreviousDue(claim.due(), claim.status()));
528	        changed.set(new Claim(claim.id(), claim.sheetId(), claim.personId(), claim.amount(), claim.date(),
529	                claim.note(), to, claim.number(), settledDue,
530	                change.action() == ClaimAction.OPEN ? change.by() : claim.openedBy(), claim.stated(), claim.statedDue(), claim.corrects(), claim.dueBy(), claim.deferredUntil(), claim.proofs(), claim.splitFrom(), claim.ref(), claim.tags()));
531	    }
532	
533	    /** Whether the claim cannot be opened for want of a note: its note is empty and its due is above the sheet's note
534	     *  threshold in force on its date (none: never; a due of n/a: never). */
535	    static boolean needsNote(Claim claim, PersonRepository people, RateRepository rates, SettingRepository settings,
536	            LateCharge late) {
537	        if (claim.note() != null && !claim.note().isBlank()) {
538	            return false;
539	        }
540	        BigDecimal threshold = settings.noteThreshold(claim.sheetId(), claim.date());
541	        if (threshold == null) {
542	            return false;
543	        }
544	        BigDecimal due = late.add(claim, due(claim, people, rates, late.rounding()),
545	                settings.floor(claim.sheetId(), claim.date()));
546	        return due != null && due.compareTo(threshold) > 0;
547	    }
548	
549	    private static BigDecimal due(Claim claim, PersonRepository people, RateRepository rates, Rounding rounding) {
550	        if (claim.stated() && claim.status() != ClaimStatus.PENDING) {
551	            return claim.statedDue();
552	        }
553	        Person person = people.find(claim.sheetId(), claim.personId());
554	        return person == null ? null : ClaimDue.live(claim, person.gradeOn(claim.date()), rates, rounding);
555	    }
556	}
