560	/** Reads the body: the action is open, settle, approve, reject (which needs a reason), void (with the void reason
561	 *  chosen, if any) or resettle. */
562	public class ValidateClaimStatus {
563	    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatusChange> change)
564	            throws InvalidClaimStatusException {
565	        String action = request == null || request.action() == null ? "" : request.action().trim();
566	        ClaimAction taken = switch (action) {
567	            case "open" -> ClaimAction.OPEN;
568	            case "settle" -> ClaimAction.SETTLE;
569	            case "approve" -> ClaimAction.APPROVE;
570	            case "reject" -> ClaimAction.REJECT;
571	            case "void" -> ClaimAction.VOID;
572	            case "resettle" -> ClaimAction.RESETTLE;
573	            default -> throw new InvalidClaimStatusException("The action must be open, settle, approve, reject, void or resettle");
574	        };
575	        ClaimStatus to = switch (taken) {
576	            case OPEN, REJECT -> ClaimStatus.OPEN;
577	            case SETTLE, APPROVE, RESETTLE -> ClaimStatus.SETTLED;
578	            case VOID -> ClaimStatus.VOID;
579	        };
580	        String reason = request.reason() == null ? "" : request.reason().trim();
581	        if (taken == ClaimAction.REJECT && reason.isEmpty()) {
582	            throw new InvalidClaimStatusException("A rejection needs a reason");
583	        }
584	        change.set(new ClaimStatusChange(taken, to, request.by() == null ? "" : request.by().trim(),
585	                taken == ClaimAction.REJECT || taken == ClaimAction.VOID ? reason : ""));
586	    }
587	}
