// The sheet-wide figures shown in more than one place (the rollups, the summary and the header), worked out once
// here so every place that shows one shows the same value.

/** The statuses claims are counted by. */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID'];

/** The sheet's due-total: everyone's due-total added up, skipping n/a, leaving out the single highest and lowest
 *  when three or more people have one. */
export function useSheetDueTotal(sheetId: string): string {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  return trimmedSum(
    (people.data ?? []).map((p) =>
      personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor, cap),
    ),
  );
}

/** The sheet's settled-total and open-total: everyone's added up (not trimmed). */
export function useSheetSplit(sheetId: string): { settled: string; open: string } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const all = (people.data ?? []).map((p) =>
    personSplit(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor),
  );
  return { settled: sum(all.map((s) => s.settled)), open: sum(all.map((s) => s.open)) };
}

/** The sheet's overdue count and overdue-total: everyone's added up (the total leaving out the single highest and
 *  lowest when there are three or more people). */
export function useSheetOverdue(sheetId: string): { count: number; total: string } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const floor = useFloor(sheetId);
  const late = useLate(sheetId);
  const all = (people.data ?? []).map((p) =>
    overdue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor),
  );
  return { count: all.reduce((n, o) => n + o.count, 0), total: trimmedSum(all.map((o) => o.total)) };
}

/** How many of the sheet's claims have each status. */
export function useStatusCounts(sheetId: string): (status: ClaimStatus) => number {
  const claims = useClaims(sheetId);
  return (status) => (claims.data ?? []).filter((c) => c.status === status).length;
}
import { isOpen, type Claim } from '../claims/claims';

/** What the late charge on a sheet depends on: its today (yyyy-MM-dd, '' while it loads), its
 *  late percent in force on a date (two decimals; a claim's charge takes the one in force on each of its 30-day boundaries) and its policy date (yyyy-MM-dd; its today while blank): a claim whose `roundsOn` is
 *  before it rounds its live figures half up, one on or after it half to even; and a claim's grace in days (that of its
 *  person's grade in force on its date, in force on that date; 0 when none). */
export type Late = { today: string; pct: (date: string) => string; policy: string; grace: (claim: Claim) => number };

/** Whether the claim's live figures round half up (it rounds on a date before the policy date) rather than half to even. */
export function roundsHalfUp(claim: Claim, late: Late | undefined): boolean {
  return late !== undefined && late.policy !== '' && claim.roundsOn < late.policy;
}

/** Days since 1970-01-01 of a yyyy-MM-dd date. */
export function day(date: string): number {
  const [y, m, d] = date.split('-').map(Number);
  return Date.UTC(y, m - 1, d) / 86_400_000;
}

/** A claim's due-by (yyyy-MM-dd): fixed when it was added, the terms-th business day after its date (skipping weekends and the sheet's holidays then), by its person's own terms then, else those of their grade. */
export function dueBy(claim: Claim): string {
  return claim.dueBy;
}

/** The date a claim is late from (yyyy-MM-dd): its due-by plus its grace (see Late). */
export function lateFrom(claim: Claim, late: Late): string {
  const grace = late.grace(claim);
  return grace === 0 ? dueBy(claim) : plusDays(dueBy(claim), grace);
}

/** Whether a claim is overdue: it is open (OPEN or PENDING), not deferred, and its due-by plus its grace is before the sheet's today. */
export function isOverdue(claim: Claim, late: Late): boolean {
  return isOpen(claim) && !claim.deferred && late.today !== '' && lateFrom(claim, late) < late.today;
}

/** How many full 30 days an overdue claim is overdue (0 when it is not overdue, its due is fixed by settling, or it is a
 *  correction, which bears no late charge). */
export function lateSteps(claim: Claim, late: Late): number {
  if (claim.due !== null || claim.amount.trim().startsWith('-') || !isOverdue(claim, late)) return 0;
  return Math.floor((day(late.today) - day(lateFrom(claim, late))) / 30);
}

/** A yyyy-MM-dd date the given days after another. */
export function plusDays(date: string, days: number): string {
  return new Date((day(date) + days) * 86_400_000).toISOString().slice(0, 10);
}

/** The 30-day boundaries an overdue claim has passed (its due-by plus its grace plus 30, 60, 90 ... days, on or before today), each
 *  bearing the late percent in force on it; none when it bears no late charge (see lateSteps). */
export function lateBoundaries(claim: Claim, late: Late): string[] {
  const steps = lateSteps(claim, late);
  return Array.from({ length: steps }, (_, i) => plusDays(lateFrom(claim, late), 30 * (i + 1)));
}
import type { Claim } from '../claims/claims';
import { gradeOn, type Person } from '../people/people';
import { claimDue, rateFor, sum, type Rate } from '../rates/rates';
import type { Dated } from '../settings/settings';
import { isOverdue, type Late } from './late';

export { dueBy, isOverdue } from './late';

/** The overdue count and overdue-total (their dues, late charge included, added up, skipping n/a) of the given
 *  claims that count. */
export function overdue(
  claims: Claim[],
  rates: Rate[] | undefined,
  person: Person,
  late: Late,
  floor: Dated,
): { count: number; total: string } {
  const over = claims.filter((c) => isOverdue(c, late));
  return { count: over.length, total: sum(over.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late))) };
}
import { isOpen, type Claim } from '../claims/claims';
import { day, type Late } from '../overdue/late';
import { gradeOn, type Person } from '../people/people';
import { claimDue, rateFor, sum, type Rate } from '../rates/rates';
import type { Dated } from '../settings/settings';

/** A person's due split by age: the dues (late charge included, skipping n/a) of their open (OPEN or PENDING) claims
 *  that count, by the days from the claim's date to the sheet's today — 0 to 30, 31 to 60, 61 or more (a claim dated
 *  after today is 0 to 30). */
export function aged(
  claims: Claim[],
  rates: Rate[] | undefined,
  person: Person,
  late: Late,
  floor: Dated,
): { d30: string; d60: string; d61: string } {
  const buckets: [string[], string[], string[]] = [[], [], []];
  for (const c of claims) {
    if (!isOpen(c) || c.deferred) continue;
    const age = late.today === '' ? 0 : day(late.today) - day(c.date);
    const figure = claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late);
    buckets[age <= 30 ? 0 : age <= 60 ? 1 : 2].push(figure);
  }
  return { d30: sum(buckets[0]), d60: sum(buckets[1]), d61: sum(buckets[2]) };
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { asFlag, asString, useSearchParam } from '../../url/useSearchParam';

export const GRADES = ['A', 'B', 'C'] as const;

/** A grade a person has from a date (yyyy-MM-dd) until their next one's; a null `from` applies from the beginning of
 *  time (the first grade the person was given). */
export type PersonGrade = { grade: string; from: string | null };

/** A person on the sheet. `name` is unique on the sheet (case ignored), kept without outer spaces; `grades` are the
 *  grades recorded, by from-date, and `grade` (A, B or C) the one in force on the sheet's today.
 *  `version` goes up by one on each stored edit; an edit sends the version it was made from. `retiredFrom` (yyyy-MM-dd)
 *  is the date the person is retired from, null when not retired: a person with one counts as retired at once. `holds` are
 *  the person's holds, by from-date: an OPEN or PENDING claim of theirs dated within one, and not bound by a statement,
 *  counts in no live total. `held` is whether they have any hold. `terms` are the person's own terms in days (ahead of
 *  their grade's and the sheet's when a claim is added), null when they have none. `contact` is the person's contact
 *  (unique on the sheet; without surrounding spaces, lower-cased), null when none. */
export type Person = {
  id: number;
  sheetId: string;
  name: string;
  grade: string;
  version: number;
  retiredFrom: string | null;
  held: boolean;
  grades: PersonGrade[];
  holds: PersonHold[];
  terms: number | null;
  contact: string | null;
};

/** A hold on a person from a date until a date (yyyy-MM-dd, both included); a null `to` is open-ended. */
export type PersonHold = { from: string; to: string | null };

/** Whether a hold of the person covers the date (yyyy-MM-dd). */
export const heldOn = (person: Pick<Person, 'holds'>, on: string) =>
  (person.holds ?? []).some((h) => h.from <= on && (h.to === null || on <= h.to));

/** Whether the person's retirement date is reached on the day (yyyy-MM-dd): it is on or before it. From then on their
 *  open (OPEN or PENDING) claims not bound by a statement count in no live total, as a hold's would. */
export const retiredOn = (person: Pick<Person, 'retiredFrom'>, on: string) =>
  person.retiredFrom !== null && on !== '' && person.retiredFrom <= on;

/** The person's grade in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it. */
export function gradeOn(person: Pick<Person, 'grade' | 'grades'>, on: string): string {
  let found: PersonGrade | undefined;
  for (const g of person.grades ?? []) {
    if (g.from !== null && g.from > on) continue;
    if (found === undefined || found.from === null || (g.from !== null && g.from > found.from)) found = g;
  }
  return found?.grade ?? person.grade;
}

export const peopleKey = (sheetId: string) => ['sheet', sheetId, 'people'];

/** The sheet's people, in the order they were added. */
export function usePeople(sheetId: string) {
  return useQuery({
    queryKey: peopleKey(sheetId),
    queryFn: () => getJson<Person[]>(`/api/sheets/${encodeURIComponent(sheetId)}/people`),
  });
}

/** The id of the person whose editor is open (in the person form), or '' when the form adds. */
export const useEditingPerson = () => useSearchParam('person', asString);

/** Whether retired people are listed. Off when the screen is first opened; loading a sheet leaves it as it is. */
export const useShowRetired = () => useSearchParam('retired', asFlag);
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { heldOn, retiredOn, type Person } from '../people/people';

/** A claim's status: DRAFT when added, then OPEN and SETTLED; a clerk settling above the clerk limit makes it PENDING
 *  until a steward approves (SETTLED) or rejects (OPEN) it; a DRAFT, OPEN or PENDING claim may be VOID, as may a SETTLED one
 *  by a steward within 7 days of its settlement. */
export type ClaimStatus = 'DRAFT' | 'OPEN' | 'PENDING' | 'SETTLED' | 'VOID';

/** A claim of a person. `amount` is text with two decimals (never a float); `date` is yyyy-MM-dd; `number` (text: 1, 2, ..., or P1-1, X-1 when numbered per period) is given
 *  when the claim is opened (null for a draft or a voided claim); `due` is the due fixed when it was settled (null
 *  while its due is live, worked out from its grade's current rate); `openedBy` is who opened it (null when never
 *  opened); `stated` is whether its person's last statement bound it to the figure `statedDue` (null when it had
 *  none), which it shows while its due is not fixed; `corrects` is, for a correction (a negative amount),
 *  the number of the SETTLED claim of the same person it corrects (null for any other claim); `roundsOn` (yyyy-MM-dd)
 *  is the date that decides how its live figures round: the corrected claim's date for a correction, else its own;
 *  `dueBy` (yyyy-MM-dd) is its due-by, fixed when it was added from its person's own terms, else those of their grade, on its date;
 *  `deferred` is whether it is deferred on the sheet's today (an OPEN claim deferred until a date after it: it counts in no
 *  total, is not overdue and cannot be settled) and `deferredUntil` (yyyy-MM-dd) the date it was last deferred until (shown
 *  even once that date has passed; null when never deferred); `proofs` is its proofs count (a claim whose due is above the sheet's proof threshold
 *  on its date cannot be settled nor approved while it is 0); `splitFrom` is the number of the claim it was split from
 *  (null for any other claim); `log` is its status log, oldest first; `lockedBy` is who has its editor open (it is locked for
 *  everyone else; null when no one does). */
export type Claim = {
  id: number;
  sheetId: string;
  personId: number;
  amount: string;
  date: string;
  note: string;
  status: ClaimStatus;
  number: string | null;
  due: string | null;
  openedBy: string | null;
  stated: boolean;
  statedDue: string | null;
  corrects: string | null;
  roundsOn: string;
  dueBy: string;
  deferred: boolean;
  deferredUntil: string | null;
  proofs: number;
  splitFrom: string | null;
  log: ClaimLogLine[];
  lockedBy: string | null;
  /** Whether it was added while the period its date falls in was soft-closed. */
  lateEntry: boolean;
  /** The last day (yyyy-MM-dd) a reminder was written for it; null when never reminded. */
  reminded: string | null;
  /** Its external reference (surrounding spaces removed; no two claims of a sheet share one, case ignored); null when none. */
  ref: string | null;
  /** Its tags: each trimmed and in lower case, no repeats, sorted; empty when none. */
  tags: string[];
  /** Its comments, in the order written. */
  comments: ClaimComment[];
  /** The number of the bulk settle batch that settled it; null when none did (settled one at a time, or not settled). */
  batch: number | null;
};

/** A comment on a claim: who wrote it, the sheet's today (yyyy-MM-dd) when it was written, and its text. */
export type ClaimComment = { by: string; date: string; text: string };

/** A comment as shown: `<user> on <date>: <text>`. */
export const commentLine = (m: ClaimComment) => `${m.by} on ${m.date}: ${m.text}`;

/** One line of a claim's status log: the status it took, who made the change, the sheet's today (yyyy-MM-dd) when
 *  it was made, and the claim's due as shown at that moment (two decimals, or n/a). */
export type ClaimLogLine = { status: ClaimStatus; by: string; date: string; due: string };

/** A status log line as shown: `<STATUS> by <user> on <date> due=<due>`. */
export const logLine = (l: ClaimLogLine) => `${l.status} by ${l.by} on ${l.date} due=${l.due}`;

export const claimsKey = (sheetId: string) => ['sheet', sheetId, 'claims'];

/** Every claim on the sheet, newest first. */
export function useClaims(sheetId: string) {
  return useQuery({
    queryKey: claimsKey(sheetId),
    queryFn: () => getJson<Claim[]>(`/api/sheets/${encodeURIComponent(sheetId)}/claims`),
  });
}

/** An amount ("12.34") in whole cents, so sums are exact. */
const cents = (amount: string) => Math.round(Number(amount) * 100);

/** Whether a claim is open: OPEN, or PENDING (handled like an OPEN claim but not bound by a statement). */
export const isOpen = (c: Claim) => c.status === 'OPEN' || c.status === 'PENDING';

/** Whether a claim counts toward claimed and the totals: only OPEN, PENDING and SETTLED claims do, and no deferred one. */
export const counts = (c: Claim) => (isOpen(c) || c.status === 'SETTLED') && !c.deferred;

/** Whether a statement binds the claim now: it is stated and not PENDING. */
export const bound = (c: Claim) => c.stated && c.status !== 'PENDING';

/** The claims that count in the live totals (claimed, due-totals, a period's due-total): a person's open (OPEN or
 *  PENDING) claims dated within a hold of theirs, or any once their retirement date is reached on the sheet's today
 *  (yyyy-MM-dd), and not bound by a statement, do not; their other claims still do. */
export function live(claims: Claim[], people: Person[] | undefined, today: string): Claim[] {
  const byId = new Map((people ?? []).map((p) => [p.id, p]));
  return claims.filter((c) => {
    const p = byId.get(c.personId);
    return counts(c) && !(isOpen(c) && !bound(c) && p !== undefined && (heldOn(p, c.date) || retiredOn(p, today)));
  });
}

/** The amounts of the claims that count added up, shown with two decimals. */
export function total(claims: Claim[]): string {
  return (claims.filter(counts).reduce((sum, c) => sum + cents(c.amount), 0) / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts, isOpen, type Claim } from '../claims/claims';
import { lateBoundaries, roundsHalfUp, type Late } from '../overdue/late';
import { gradeOn, type Person } from '../people/people';
import type { Dated } from '../settings/settings';

/** A grade's rate on the sheet: `rate` is a percent as text with two decimals (never a float), in force from
 *  `from` (yyyy-MM-dd; null: from the beginning of time) through `to` (yyyy-MM-dd; null: no end). */
export type Rate = { sheetId: string; grade: string; rate: string; from: string | null; to: string | null };

export const ratesKey = (sheetId: string) => ['sheet', sheetId, 'rates'];

/** The sheet's rates, by grade then from-date. */
export function useRates(sheetId: string) {
  return useQuery({
    queryKey: ratesKey(sheetId),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheetId)}/rates`),
  });
}

/** The grade's rate in force on a date (yyyy-MM-dd): the one with the latest from-date on or before it, a rate
 *  with no from-date applying from the beginning of time; undefined when none applies, or that rate's to-date is
 *  before the date. */
export function rateFor(rates: Rate[] | undefined, grade: string, on: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates ?? []) {
    if (r.grade !== grade || (r.from !== null && r.from > on)) continue;
    if (found === undefined || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found === undefined || (found.to !== null && found.to < on) ? undefined : found.rate;
}

/** A two-decimal number ("12.34") in hundredths, exactly. */
function hundredths(value: string): bigint {
  const t = value.trim();
  const negative = t.startsWith('-');
  const [whole, frac = ''] = (negative ? t.slice(1) : t).split('.');
  const h = BigInt(whole || '0') * 100n + BigInt((frac + '00').slice(0, 2));
  return negative ? -h : h;
}

/** Hundredths shown with two decimals. */
function shown(h: bigint): string {
  const sign = h < 0n ? '-' : '';
  const a = h < 0n ? -h : h;
  return `${sign}${a / 100n}.${String(a % 100n).padStart(2, '0')}`;
}

/** What is due on an amount at a rate: amount × rate / 100, rounded to two decimals (half to even, or half up when
 *  `halfUp`); 'n/a' when there is no rate. */
export function due(amount: string, rate: string | undefined, halfUp = false): string {
  if (rate === undefined) return 'n/a';
  return shown(percentOf(amount, rate, 1, halfUp));
}

/** `times` × value × pct / 100 in hundredths, rounded to two decimals: half to even, or half up (away from zero)
 *  when `halfUp`. */
function percentOf(value: string, pct: string, times: number, halfUp: boolean): bigint {
  const p = hundredths(value) * hundredths(pct) * BigInt(times); // in 1/10000 of a hundredth
  const a = p < 0n ? -p : p;
  const q = a / 10000n;
  const rem = a % 10000n;
  const r = rem > 5000n || (rem === 5000n && (halfUp || q % 2n === 1n)) ? q + 1n : q;
  return p < 0n ? -r : r;
}

/** A claim's due: the figure fixed when it was settled, otherwise the one its person's last statement bound it to (never while PENDING),
 *  otherwise its amount at the rate in force on its date. Given the sheet's late charge, an overdue claim's figure gains,
 *  for every full 30 days overdue, the late percent in force on that boundary (its due-by plus 30, 60, 90 ... days) of
 *  it plus the charges of the boundaries before it (compounding), each rounded like the claim and added up (never bound by a statement; frozen in when settled). Last, the live
 *  due is at least the sheet's floor in force on its date (a correction has no floor). Both round by the sheet's
 *  policy date (see Late). */
export function claimDue(claim: Claim, rate: string | undefined, floor: Dated, late?: Late): string {
  if (claim.due !== null) return claim.due;
  const halfUp = roundsHalfUp(claim, late);
  const figure = claim.stated && claim.status !== 'PENDING' ? (claim.statedDue ?? 'n/a') : due(claim.amount, rate, halfUp);
  if (figure === 'n/a') return figure;
  const boundaries = late === undefined ? [] : lateBoundaries(claim, late);
  const charged = boundaries.reduce((t, b) => t + percentOf(shown(t), late!.pct(b), 1, halfUp), hundredths(figure));
  const f = hundredths(floor(claim.date));
  return shown(charged < f && hundredths(claim.amount) >= 0n ? f : charged);
}

/** The sum of a person's figures: the figures of their claims that count (each at the rate, of the grade in force,
 *  on its date, with its late charge) added up; 'n/a' when their grade has no rate today and none of those claims has
 *  a figure. */
function personFigures(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated): string {
  const counted = claims.filter(counts);
  const figures = counted.map((c) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late));
  if (rateFor(rates, gradeOn(person, late.today), late.today) === undefined && figures.every((f) => f === 'n/a')) return 'n/a';
  return sum(figures);
}

/** A person's settled-total and open-total: the figures (see personFigures) of their SETTLED claims that count
 *  (frozen when settled, corrections included), and of their OPEN and PENDING ones, each added up, skipping n/a.
 *  Together they make the sum of their figures, before the cap. */
export function personSplit(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated): { settled: string; open: string } {
  const figure = (c: Claim) => claimDue(c, rateFor(rates, gradeOn(person, c.date), c.date), floor, late);
  const counted = claims.filter(counts);
  return {
    settled: sum(counted.filter((c) => c.status === 'SETTLED').map(figure)),
    open: sum(counted.filter((c) => c.status !== 'SETTLED').map(figure)),
  };
}

/** A person's due-total: the sum of their figures (see personFigures), at most the sheet's cap (null: none); 'n/a'
 *  is not capped. */
export function personDue(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap) ? shown(hundredths(cap)) : total;
}

/** A person's excess: how far the sum of their figures is above the sheet's cap; 0.00 when it is not (or with no
 *  cap, or an n/a due-total). */
export function personExcess(claims: Claim[], rates: Rate[] | undefined, person: Person, late: Late, floor: Dated, cap: string | null): string {
  const total = personFigures(claims, rates, person, late, floor);
  return total !== 'n/a' && cap !== null && hundredths(total) > hundredths(cap)
    ? shown(hundredths(total) - hundredths(cap))
    : '0.00';
}

/** A candidate rate: a percent 0.00 or more with up to two decimals (as the rate form takes it). */
export const RATE_PATTERN = /^\d{1,5}(\.\d{1,2})?$/;

/** What a candidate rate would change if it applied to the grade on every date: of the OPEN and PENDING claims whose
 *  person is on the grade on the claim's date, how many would show a different due, and the sum of the differences
 *  (new due minus current due; an n/a due counts as 0.00). A claim bound by a statement keeps its due, so never
 *  changes; settled claims are not looked at. */
export function ratePreview(
  claims: Claim[],
  people: Person[],
  rates: Rate[] | undefined,
  grade: string,
  pct: string,
  late: Late,
  floor: Dated,
): { count: number; diff: string } {
  const byId = new Map(people.map((p) => [p.id, p]));
  const value = (d: string) => (d === 'n/a' ? 0n : hundredths(d));
  let count = 0;
  let diff = 0n;
  for (const c of claims) {
    const person = byId.get(c.personId);
    if (!isOpen(c) || person === undefined || gradeOn(person, c.date) !== grade) continue;
    const now = claimDue(c, rateFor(rates, grade, c.date), floor, late);
    const then = claimDue(c, pct, floor, late);
    if (now === then) continue;
    count++;
    diff += value(then) - value(now);
  }
  return { count, diff: shown(diff) };
}

/** Two-decimal values added up, skipping 'n/a'. */
export function sum(values: string[]): string {
  return shown(values.filter((v) => v !== 'n/a').reduce((s, v) => s + hundredths(v), 0n));
}

/** Two-decimal values added up, skipping 'n/a', leaving out the single highest and the single lowest when three
 *  or more are left. */
export function trimmedSum(values: string[]): string {
  const figures = values.filter((v) => v !== 'n/a').map(hundredths).sort((a, b) => (a < b ? -1 : a > b ? 1 : 0));
  const kept = figures.length >= 3 ? figures.slice(1, -1) : figures;
  return shown(kept.reduce((s, v) => s + v, 0n));
}

